def _check_primitive(key, value, prop):
    t = prop.get('type')
    if t == 'string' and not isinstance(value, str):
        return f'invalid_type:{key}'
    if t == 'integer' and (not isinstance(value, int) or isinstance(value, bool)):
        return f'invalid_type:{key}'
    if t == 'number' and not isinstance(value, (int, float)) or isinstance(value, bool):
        return f'invalid_type:{key}'
    if t == 'boolean' and not isinstance(value, bool):
        return f'invalid_type:{key}'
    if t == 'enum' and value not in prop.get('enum', []):
        return f'invalid_enum:{key}'
    if isinstance(value, str):
        if len(value) < prop.get('minLength', 0): return f'below_min:{key}'
        if len(value) > prop.get('maxLength', 10**9): return f'above_max:{key}'
        import re as _re
        p = prop.get('pattern')
        if p and not _re.search(p, value): return f'pattern_mismatch:{key}'
    return None


def generic_validate_arguments(tool_id: str, arguments: Any) -> list[str]:
    """Validate WRITE arguments against the frozen tool contract schema."""
    if tool_id not in WRITE_CONTRACTS:
        return ['unknown_tool']
    if not isinstance(arguments, Mapping):
        return ['arguments_not_object']
    schema = WRITE_CONTRACTS[tool_id]['input_schema']
    props = schema.get('properties', {})
    required = schema.get('required', [])
    violations: list[str] = []
    for key in sorted(arguments):
        if key not in props:
            violations.append(f'unknown_argument:{key}')
    for name in required:
        if name not in arguments:
            violations.append(f'missing_required:{name}')
    for name, value in arguments.items():
        if name not in props: continue
        err = _check_primitive(name, value, props[name])
        if err: violations.append(err)
    return violations


WRITE_TOOL_IDS: tuple[str, ...] = tuple(sorted(WRITE_CONTRACTS))
